let me=null, engineers=[], requests=[], selectedSpecialty='全部', searchTerm='', poll=null, currentMessages='', routeToken=0;
const specialties=[
 {name:'机械工程',icon:'⚙',en:'MECHANICAL',desc:'把力、运动、热和流体变成可靠的机器。',intro:'机械工程把科学原理变成可运转、可制造、可维护的机器。从齿轮到发动机，从机械臂到散热系统，都要在受力、热量和成本之间取得平衡。',research:['把力、运动、热和流体变成可靠的机器。设计的不只是外形，还包括尺寸、受力、散热、制造和维修。','机械设计关注零件怎样传力；热流体关注冷却、发动机与空调；制造工程关注零件如何被稳定地生产。'],courses:[{en:'Statics and Dynamics',name:'工程静力学与动力学',desc:'算支架受力和机械臂运动'},{en:'Mechanics of Materials',name:'材料力学',desc:'判断零件会不会弯曲或断裂'},{en:'Thermodynamics',name:'热力学',desc:'计算热量如何转化为功'},{en:'Fluid Mechanics',name:'流体力学',desc:'研究管道阻力与气流'},{en:'Machine Design',name:'机械设计',desc:'选择齿轮、轴承和连接方式'},{en:'CAD and Manufacturing',name:'三维设计与制造',desc:'把模型变成带尺寸公差的零件图'}],jobs:'机械设计工程师：建模、计算并修改零件；热管理工程师：分析温度与冷却流量；制造工程师：排查加工误差并改进工艺。常见于汽车、机器人、医疗器械和工业设备行业。',tradeoff:'电动汽车电池冷却：先规定允许温度和温差，再设计冷却板及流道，测试不同功率下的温度。加大泵流量可改善冷却，却增加能耗；工程师要同时比较温度、压降、重量和维修成本。',distinguish:'与材料工程相比，机械更关注部件和系统如何工作；材料更关注材料内部结构与性能。喜欢画产品外形，也需要体验受力计算和反复测试。',project:{title:'用同样多的纸设计抗弯支架',time:'2至4小时完成初版，再用一次课外活动做改进。',start:'材料为A4纸、胶带、两本书和相同硬币。固定两支点间距20厘米，做平板、折槽和三角截面三种结构；逐枚加硬币，记录首次明显变形时的载荷；每种重复3次。',evidence:'比较最大承载质量与支架自身质量之比，注明截面尺寸、加载位置和失败形态。',deepen:'根据首轮失败位置修改折痕，再测试；可用CAD画出修改前后的截面。不要只展示最好的一次。',fit:'你是否喜欢把一个结构改到更稳、更轻？失败后是否愿意追查原因？高中物理力学、热学和数学是直接起点。',links:[{name:'MIT OCW',url:'https://ocw.mit.edu/search/?d=Mechanical%20Engineering',step:'先搜索Statics或Design and Manufacturing，试看一节课并画受力图。'}],books:[{title:'The Way Things Work Now',author:'David Macaulay',note:'挑一种机构，解释每个部件的作用。'},{title:'To Engineer Is Human',author:'Henry Petroski',note:'关注工程失败怎样改变设计。'}],questions:['我能否用一张图解释系统怎样工作，以及限制条件是什么？','哪一项数据推翻了我的最初猜测？如果没有，测试是否足够充分？','如果再给我一天，我会优先改哪个变量，为什么？'],outcome:'一页问题与需求说明、一张设计或流程图、一份原始数据表，以及一段有证据支持的改进解释。'}},
 {name:'电气与电子工程',icon:'⌁',en:'ELECTRICAL',desc:'让电能或信息按设计被产生、传输和处理。',intro:'电气与电子工程研究电能和信息的产生、传输与处理。从电网、电机到芯片、通信，核心是让看不见的电流和信号按预期工作。',research:['让电能或信息按照设计被产生、传输和处理。电气侧重供电、电机与电力电子；电子侧重电路、器件、信号与通信。两者在很多大学属于同一院系。','电力系统研究电网；微电子研究半导体与芯片；通信研究信号传输；控制与仪器研究测量和调节。'],courses:[{en:'Circuit Analysis',name:'电路分析',desc:'求电压电流并理解电阻电容'},{en:'Digital Electronics',name:'数字电子',desc:'用逻辑门实现判断'},{en:'Signals and Systems',name:'信号与系统',desc:'理解滤波和频率'},{en:'Electromagnetics',name:'电磁学',desc:'解释天线与电机'},{en:'Semiconductor Devices',name:'半导体器件',desc:'理解二极管与晶体管'},{en:'Power Electronics',name:'电力电子',desc:'控制电能转换'}],jobs:'硬件工程师：画原理图、设计电路板并测波形；测试工程师：找噪声和故障；电力工程师：规划供电和保护；芯片设计工程师：设计或验证数字电路。',tradeoff:'手机无线通信：信息先编码、调制，经射频电路与天线发出，接收端再恢复信息。天线大小受空间限制，功耗影响续航，干扰影响可靠性，因此不能只追求信号更强。',distinguish:'计算机工程更集中在计算硬件和软硬件协同；电气电子的范围还包括电网、通信、电磁和模拟电路。',project:{title:'设计有滞回的自动夜灯',time:'2至4小时完成初版，再用一次课外活动做改进。',start:'先用电路仿真，或使用USB供电开发板、光敏电阻和LED。记录明亮与昏暗时的读数；设定开灯阈值；在临界亮度下观察闪烁，再把开灯和关灯阈值分开。',evidence:'记录误触发次数、响应时间及不同阈值下的稳定性；保持传感器方向和测试光源一致。',deepen:'加入短时平均，比较平滑噪声与响应变慢的取舍。只使用低压套件，不接市电。',fit:'你是否愿意面对看不见的电流，用数据和仪器定位问题？高中电学、波和数学帮助很大。',links:[{name:'Arduino Education',url:'https://www.arduino.cc/education',step:'从传感器读数和LED开始。'},{name:'MIT OCW',url:'https://ocw.mit.edu/',step:'搜索Circuits。'}],books:[{title:'Code',author:'Charles Petzold',note:'从开关理解信息表示。'},{title:'The Art of Electronics',author:'Paul Horowitz and Winfield Hill',note:'作为电路参考书选读，不必通读。'}],questions:['我能否用一张图解释系统怎样工作，以及限制条件是什么？','哪一项数据推翻了我的最初猜测？如果没有，测试是否足够充分？','如果再给我一天，我会优先改哪个变量，为什么？'],outcome:'一页问题与需求说明、一张设计或流程图、一份原始数据表，以及一段有证据支持的改进解释。'}},
 {name:'计算机工程',icon:'⌘',en:'COMPUTER',desc:'研究程序如何在真实硬件上运行。',intro:'计算机工程连接逻辑电路、处理器、内存、操作系统和嵌入式设备，重点不只在写应用，而在性能、功耗、时序和可靠性。',research:['研究程序如何在真实硬件上运行，连接逻辑电路、处理器、内存、操作系统和嵌入式设备。重点不只在写应用，而在性能、功耗、时序和可靠性。','计算机体系结构研究处理器；嵌入式系统把计算装进设备；数字设计实现硬件逻辑；物联网连接传感器与网络。'],courses:[{en:'Digital Logic',name:'数字逻辑',desc:'从逻辑门搭建加法器'},{en:'Computer Architecture',name:'计算机体系结构',desc:'理解指令与缓存'},{en:'Embedded Systems',name:'嵌入式系统',desc:'读取传感器并控制设备'},{en:'Operating Systems',name:'操作系统',desc:'管理进程内存'},{en:'Computer Networks',name:'计算机网络',desc:'理解数据包与协议'},{en:'Hardware Verification',name:'硬件验证',desc:'检查电路在各种输入下是否正确'}],jobs:'固件工程师：编写设备底层程序；嵌入式工程师：联调传感器、通信和控制；硬件验证工程师：设计测试找逻辑漏洞；体系结构工程师：比较计算性能和能耗。',tradeoff:'智能手表：传感器产生数据，微控制器定时读取并处理，通过无线模块同步。提高采样频率可能提升细节，却消耗更多电量；断网时还要决定怎样保存数据和重试。',distinguish:'Computer Science通常更广泛研究算法、软件和计算理论；Computer Engineering通常更强调数字硬件。不同大学交叉程度很大，要看必修课。',project:{title:'制作能应对传感器故障的数据记录器',time:'2至4小时完成初版，再用一次课外活动做改进。',start:'用开发板接温度或光照传感器，也可先用模拟数据。每秒记录一次时间和读数；人为拔掉传感器或提供异常值；程序应标记错误并继续运行。',evidence:'比较有效数据比例、采样间隔偏差及异常恢复时间，保存原始日志。',deepen:'把采样周期改为0.2秒和5秒，比较数据量与遗漏短时变化的程度；为断网设计缓存。',fit:'你是否对程序为什么卡住、数据怎样进到处理器感兴趣？数学、基础编程和电学都值得体验。',links:[{name:'Nand2Tetris',url:'https://www.nand2tetris.org/',step:'先完成布尔逻辑与逻辑门项目，再决定是否继续。'},{name:'Arduino Education',url:'https://www.arduino.cc/education',step:'从硬件入门开始。'}],books:[{title:'Code',author:'Charles Petzold',note:'从开关理解信息表示。'},{title:'The Elements of Computing Systems',author:'Noam Nisan and Shimon Schocken',note:'配合网站逐个做项目。'}],questions:['我能否用一张图解释系统怎样工作，以及限制条件是什么？','哪一项数据推翻了我的最初猜测？如果没有，测试是否足够充分？','如果再给我一天，我会优先改哪个变量，为什么？'],outcome:'一页问题与需求说明、一张设计或流程图、一份原始数据表，以及一段有证据支持的改进解释。'}},
 {name:'土木工程',icon:'⌂',en:'CIVIL',desc:'设计和维护人们共同使用的基础设施。',intro:'土木工程研究桥梁、道路、建筑、地基、供水与排水等基础设施，对象往往使用几十年，需要考虑荷载变化、自然环境和长期维护。',research:['设计和维护人们共同使用的基础设施，包括桥梁、道路、建筑结构、地基、供水和排水。工程对象往往使用几十年，需要考虑荷载变化、自然环境和维护。','结构工程关注承重；岩土工程关注土和基础；交通工程关注道路与出行；水利与市政关注水的输送和管理。'],courses:[{en:'Structural Analysis',name:'结构分析',desc:'求梁与桁架内力'},{en:'Geotechnical Engineering',name:'岩土工程',desc:'判断地基沉降'},{en:'Construction Materials',name:'建筑材料',desc:'理解混凝土与钢'},{en:'Hydraulics',name:'水力学',desc:'计算管道和明渠流动'},{en:'Transportation Engineering',name:'交通工程',desc:'分析流量和路口'},{en:'Surveying',name:'测量学',desc:'获得准确的位置高程'}],jobs:'结构工程师：计算承重并出图；岩土工程师：解释勘察数据；交通工程师：分析路口或公共交通；施工工程师：协调工序、质量与现场问题。',tradeoff:'跨海大桥：结构团队考虑车辆与风荷载，岩土团队确定基础，材料与维护团队考虑海水腐蚀。一次建造成本较低的方案，可能带来更高的长期维护费用。',distinguish:'建筑学更关注空间、使用体验与建筑表达；土木结构更关注承载、安全与建造。两者需要共同协调。',project:{title:'设计同跨度的纸桥',time:'2至4小时完成初版，再用一次课外活动做改进。',start:'固定纸张数量、胶带长度和桥跨度30厘米，设计梁桥与桁架模型。用托盘逐步加硬币，保持加载位置一致；每种做3个样本。',evidence:'记录承载质量、结构质量、跨中挠度和破坏位置；用照片标出受拉和受压的构件。',deepen:'在相同材料预算下改进节点连接。模型测试只比较模型，不直接代表真实桥梁安全。',fit:'你是否喜欢空间受力、城市基础设施和长期公共影响？物理力学、数学与地理观察很有帮助。',links:[{name:'MIT OCW',url:'https://ocw.mit.edu/',step:'搜索Structural Mechanics和Civil Engineering，从梁的受力题开始。'}],books:[{title:'Structures Or Why Things Don\'t Fall Down',author:'J. E. Gordon',note:'入门读物。'},{title:'Why Buildings Stand Up',author:'Mario Salvadori',note:'边读边画荷载传递路径。'}],questions:['我能否用一张图解释系统怎样工作，以及限制条件是什么？','哪一项数据推翻了我的最初猜测？如果没有，测试是否足够充分？','如果再给我一天，我会优先改哪个变量，为什么？'],outcome:'一页问题与需求说明、一张设计或流程图、一份原始数据表，以及一段有证据支持的改进解释。'}},
 {name:'化学工程',icon:'⚗',en:'CHEMICAL',desc:'把实验室原理变成可放大的生产过程。',intro:'化学工程研究如何把实验室的反应原理变成安全、稳定、可放大的生产过程，应用于药物、食品、电池、能源和水处理。',research:['把实验室原理变成安全、稳定、可放大的生产过程。重点是物料流向、热量、反应速度、分离与控制，应用于药物、食品、电池、能源和水处理。','反应工程选择反应器；分离工程提高纯度；过程系统工程优化整条工艺；生物化工把生物过程用于生产。'],courses:[{en:'Mass and Energy Balances',name:'物料与能量衡算',desc:'核算物质与热量去向'},{en:'Transport Phenomena',name:'传递现象',desc:'研究流动传热和扩散'},{en:'Reaction Engineering',name:'反应工程',desc:'选反应器及停留时间'},{en:'Separation Processes',name:'分离过程',desc:'理解蒸馏过滤和膜'},{en:'Process Control',name:'过程控制',desc:'维持温度流量'},{en:'Process Design',name:'流程设计',desc:'综合设备成本与安全'}],jobs:'工艺工程师：分析生产数据、调整条件；过程设计工程师：计算设备与流程；制药生产工程师：提高批次一致性；过程安全工程师：识别失控与泄漏风险。',tradeoff:'药物放大生产：小烧杯容易散热，大反应器的体积增长快于表面积，不能直接把材料和时间都等比例放大。团队需重新评估混合、传热、反应速率、分离和质量控制。',distinguish:'化学更常研究物质、结构与反应机理；化工更常研究如何连续或批量生产。喜欢化学实验，也要尝试物理、数学和流程计算。',project:{title:'比较不同尺寸容器的冷却速度',time:'2至4小时完成初版，再用一次课外活动做改进。',start:'使用温热水和两个尺寸不同但材质相近的容器，记录水量与暴露面积；每分钟测温，画温度与时间图；保持初始水温和环境尽量相同。',evidence:'比较达到同一目标温度的时间，并讨论水量、表面积、容器厚度等混杂因素。',deepen:'设计保温或散热方案，再测一次。这个实验体现传热与尺度问题，不能直接预测工业反应器。',fit:'你是否愿意追踪每一股物流、检查单位和守恒？化学与物理并重，数学能力尤其重要。',links:[{name:'LearnChemE',url:'https://learncheme.com/simulations/',step:'先选物料衡算或传热模拟，只改一个变量，先预测再观察。'}],books:[{title:'The Alchemy of Air',author:'Thomas Hager',note:'理解合成氨的科学、工业与社会背景。'},{title:'Elementary Principles of Chemical Processes',author:'Richard Felder 等',note:'选读物料衡算。'}],questions:['我能否用一张图解释系统怎样工作，以及限制条件是什么？','哪一项数据推翻了我的最初猜测？如果没有，测试是否足够充分？','如果再给我一天，我会优先改哪个变量，为什么？'],outcome:'一页问题与需求说明、一张设计或流程图、一份原始数据表，以及一段有证据支持的改进解释。'}},
 {name:'材料科学与工程',icon:'◈',en:'MATERIALS',desc:'研究成分、结构、加工与性能的关系。',intro:'材料科学与工程研究成分、微观结构、加工和性能之间的关系。相同成分经过不同加工，可能产生完全不同的强度、韧性或导电性。',research:['研究成分、微观结构、加工和性能之间的关系。相同化学成分经过不同加工，可能产生不同强度、韧性、导电性或耐腐蚀性。','金属与陶瓷关注结构和耐热；高分子关注塑料与软材料；电子材料用于器件；复合材料组合不同材料的优势。'],courses:[{en:'Structure of Materials',name:'材料结构',desc:'理解原子排列与缺陷'},{en:'Materials Thermodynamics',name:'材料热力学',desc:'判断相的稳定性'},{en:'Mechanical Behavior',name:'力学性能',desc:'区分强度韧性和疲劳'},{en:'Polymer Science',name:'高分子科学',desc:'理解链结构'},{en:'Materials Characterization',name:'材料表征',desc:'用显微与衍射判断结构'},{en:'Materials Processing',name:'材料加工',desc:'研究热处理和成形'}],jobs:'材料研发工程师：设计配方和测试方案；失效分析工程师：找开裂或腐蚀根因；电池材料工程师：研究电极与界面；质量工程师：检查批次性能是否稳定。',tradeoff:'飞机碳纤维复合材料：纤维方向影响承载能力，树脂负责结合与传递载荷。减重有价值，但制造缺陷、层间损伤、检测和维修同样决定材料能否真正使用。',distinguish:'机械工程主要设计部件；材料工程进一步追问材料为什么具有某种性能。强度高不等于韧性好，也不意味着所有方向都一样强。',project:{title:'测试纸纤维方向对弯曲性能的影响',time:'2至4小时完成初版，再用一次课外活动做改进。',start:'从同一张纸沿两个垂直方向裁相同尺寸纸条，固定悬臂长度，在末端加同样小载荷，测下垂；每个方向至少5条。',evidence:'记录挠度、尺寸和试样方向，计算平均值与范围；注意纸张湿度和折痕。',deepen:'用胶带或另一层纸做复合结构，在控制总质量后比较。纸模型展示方向效应，不等同于碳纤维实测性能。',fit:'你是否会问为什么一个物体脆、另一个耐弯？化学、物理与实验观察能直接连接这个专业。',links:[{name:'Materials Project 文档',url:'https://docs.materialsproject.org/',step:'查看材料性质如何组织，理解计算预测与实验测量的区别；数据库操作可能需要账户。'}],books:[{title:'Stuff Matters',author:'Mark Miodownik',note:'从日常材料建立直觉。'},{title:'The New Science of Strong Materials',author:'J. E. Gordon',note:'关注结构与破坏。'}],questions:['我能否用一张图解释系统怎样工作，以及限制条件是什么？','哪一项数据推翻了我的最初猜测？如果没有，测试是否足够充分？','如果再给我一天，我会优先改哪个变量，为什么？'],outcome:'一页问题与需求说明、一张设计或流程图、一份原始数据表，以及一段有证据支持的改进解释。'}},
 {name:'生物医学工程',icon:'✚',en:'BIOMEDICAL',desc:'把工程方法用于医疗与人体问题。',intro:'生物医学工程把工程方法用于医疗与人体，开发诊断、治疗、康复或监测技术。系统必须考虑生物差异、可靠性、使用者和临床证据。',research:['把工程方法用于医疗与人体问题，开发诊断、治疗、康复或监测技术。系统必须考虑生物差异、可靠性、使用者和临床证据。','生物力学研究人体受力；医学成像研究内部结构的获取；生物材料研究身体与材料的相互作用；生物仪器研究信号采集。'],courses:[{en:'Human Physiology',name:'人体生理学',desc:'理解器官功能'},{en:'Biomechanics',name:'生物力学',desc:'分析关节与步态'},{en:'Biomedical Signals',name:'生物医学信号',desc:'处理心电等噪声数据'},{en:'Medical Imaging',name:'医学成像',desc:'理解图像形成'},{en:'Biomaterials',name:'生物材料',desc:'考虑组织反应'},{en:'Medical Device Design',name:'医疗器械设计',desc:'从用户需求到验证'}],jobs:'器械研发工程师：设计原型并验证需求；影像算法工程师：处理图像；测试工程师：建立可重复的性能测试；临床工程师：支持医疗设备运行。部分专门研发岗位常需研究生训练。',tradeoff:'人工髋关节：材料要能承载并减少磨损，几何形状要适合受力与固定，还需考虑磨损颗粒和生物反应。实验室性能优秀之后，仍有制造、验证与临床评价环节。',distinguish:'医学主要训练诊断治疗患者；生物医学工程主要训练开发和验证技术。喜欢生物不代表一定喜欢电路、力学和数据处理，要看课程方向。',project:{title:'设计适合手部活动受限者的开瓶辅助器',time:'2至4小时完成初版，再用一次课外活动做改进。',start:'用纸板、泡棉或橡皮筋做增大握持面积的原型。固定同一个空瓶及拧紧方式，比较不同把手形状；先用机械夹具或同一测试者完成重复测试。',evidence:'记录所需作用力的近似值、滑脱次数、操作步骤和舒适度；把主观感受与客观数据分开。',deepen:'用绳与已知力臂估算转矩，测试改进；不把课堂原型当医疗产品，不收集同学健康信息。',fit:'你是否愿意同时理解人体需求和工程限制？生物、物理、数学都重要，某些方向也高度依赖编程。',links:[{name:'NIH NIBIB',url:'https://www.nibib.nih.gov/science-education/science-topics',step:'先读Biomaterial Technologies或Medical Imaging，再画技术与人体的交互。'}],books:[{title:'The Body A Guide for Occupants',author:'Bill Bryson',note:'补充人体背景。'},{title:'Biomedical Engineering Bridging Medicine and Technology',author:'W. Mark Saltzman',note:'按兴趣选章节。'}],questions:['我能否用一张图解释系统怎样工作，以及限制条件是什么？','哪一项数据推翻了我的最初猜测？如果没有，测试是否足够充分？','如果再给我一天，我会优先改哪个变量，为什么？'],outcome:'一页问题与需求说明、一张设计或流程图、一份原始数据表，以及一段有证据支持的改进解释。'}},
 {name:'航空航天工程',icon:'↗',en:'AEROSPACE',desc:'研究飞行器如何升空、推进并保持稳定。',intro:'航空航天工程研究飞行器的升力、推进、稳定与结构。航空面向大气内飞行，航天还涉及轨道、真空、辐射和通信延迟。',research:['研究飞行器如何产生升力、推进、保持稳定并承受环境。航空面对大气内飞行；航天还涉及轨道、真空、辐射和通信延迟。','空气动力学研究气流；推进研究发动机；飞行控制管理姿态；结构研究轻量与强度；轨道与任务设计规划航天飞行。'],courses:[{en:'Aerodynamics',name:'空气动力学',desc:'理解升力阻力'},{en:'Flight Dynamics',name:'飞行动力学',desc:'分析稳定与操纵'},{en:'Propulsion',name:'推进',desc:'研究推力与效率'},{en:'Aerospace Structures',name:'航空结构',desc:'设计轻质承重'},{en:'Orbital Mechanics',name:'轨道力学',desc:'计算轨道变化'},{en:'Control Systems',name:'控制系统',desc:'让姿态跟随指令'}],jobs:'气动工程师：仿真和风洞测试；结构工程师：计算载荷与疲劳；飞控工程师：建模验证控制律；推进工程师：测试发动机部件；航天系统工程师：协调任务约束。',tradeoff:'火星探测任务：轨道设计决定抵达条件，进入大气需要热防护，着陆需要导航与减速，落地后仍要供电和通信。增加仪器会增加质量，也会影响燃料与发射约束。',distinguish:'机械工程基础更广；航空航天把力学、热流体和控制集中于飞行系统。相关行业也吸收机械、电气、材料和计算机毕业生。',project:{title:'优化纸滑翔机的重心位置',time:'2至4小时完成初版，再用一次课外活动做改进。',start:'使用同一纸型与机翼结构，在机头逐步添加相同小纸夹。室内固定释放高度和方式，每种位置飞5次，记录距离与偏航。',evidence:'比较平均距离、范围和稳定着陆比例；不要仅记录最远一次。标注重心相对机翼的位置。',deepen:'增加尾翼或改变翼面，分别测试；讨论重心过前与过后为何可能影响稳定性。避免道路、高处或人群。',fit:'你是否喜欢把多个严格约束一起算清楚？物理力学、数学、编程都很有用，课程数学密度通常较高。',links:[{name:'NASA Beginner\'s Guide',url:'https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/',step:'从升力、阻力与稳定性开始。'}],books:[{title:'Introduction to Flight',author:'John D. Anderson',note:'选择气动与飞行性能章节，先理解图和量的关系。'}],questions:['我能否用一张图解释系统怎样工作，以及限制条件是什么？','哪一项数据推翻了我的最初猜测？如果没有，测试是否足够充分？','如果再给我一天，我会优先改哪个变量，为什么？'],outcome:'一页问题与需求说明、一张设计或流程图、一份原始数据表，以及一段有证据支持的改进解释。'}},
 {name:'环境工程',icon:'♧',en:'ENVIRONMENTAL',desc:'设计减少污染和保护资源的系统。',intro:'环境工程用工程方法减少污染、保护资源。需要识别污染源、理解迁移与转化、选择处理方法，并通过监测判断是否有效。',research:['设计减少污染和保护资源的系统。需要识别污染源、理解迁移与转化、选择处理方法，并通过监测判断是否有效。','水处理研究溶解与悬浮污染物；空气污染控制研究颗粒与气体；固废资源化研究回收；环境监测结合化学、生物与传感。'],courses:[{en:'Environmental Chemistry',name:'环境化学',desc:'理解污染物形态'},{en:'Environmental Microbiology',name:'环境微生物',desc:'理解生物处理'},{en:'Water Treatment',name:'水处理',desc:'选择沉淀过滤消毒'},{en:'Air Pollution Control',name:'大气污染控制',desc:'处理颗粒与废气'},{en:'Hydrology',name:'水文学',desc:'分析径流'},{en:'Environmental Modeling',name:'环境建模',desc:'预测浓度变化'}],jobs:'水处理工程师：分析水质与工艺表现；环境咨询工程师：做调查和方案比较；监测工程师：核查采样质量；资源回收工程师：设计废物流分选与利用。',tradeoff:'污水处理厂：沉淀主要去除部分悬浮物，生物过程降低可生物降解污染负荷，再通过后续处理满足用途。水变清不等于无病原体，也不代表溶解污染物已经去除。',distinguish:'环境科学更常解释环境过程；环境工程更常设计并运行干预系统。与化工都用传递和反应原理，但目标与污染浓度范围可能不同。',project:{title:'比较过滤材料的效果与代价',time:'2至4小时完成初版，再用一次课外活动做改进。',start:'用少量土与清水配制同一批模拟浑水，比较咖啡滤纸与清洁砂层。固定进水体积和容器，用相同光照背景拍摄，并记录过滤时间。',evidence:'用照片亮度或可见标记作浑浊程度的近似指标，报告方法局限；记录出水量与堵塞情况。',deepen:'设计两级过滤并比较流速和视觉清澈度。所有出水均不可饮用；实验不验证消毒或化学净化效果。',fit:'你是否愿意处理真实环境中波动很大的数据？化学、生物、物理与数据分析都能发挥作用。',links:[{name:'US EPA 学生资源',url:'https://www.epa.gov/students',step:'选择水或废弃物主题，寻找一个可量化的校园问题。'}],books:[{title:'Silent Spring',author:'Rachel Carson',note:'理解污染的生态背景，部分内容具有历史语境。'},{title:'Introduction to Environmental Engineering',author:'Mackenzie L. Davis and David A. Cornwell',note:'选读水处理。'}],questions:['我能否用一张图解释系统怎样工作，以及限制条件是什么？','哪一项数据推翻了我的最初猜测？如果没有，测试是否足够充分？','如果再给我一天，我会优先改哪个变量，为什么？'],outcome:'一页问题与需求说明、一张设计或流程图、一份原始数据表，以及一段有证据支持的改进解释。'}},
 {name:'机器人与机电一体化',icon:'⌬',en:'ROBOTICS',desc:'把机械、传感器、电路与程序连接起来。',intro:'机器人与机电一体化把机械、传感器、电路、程序与控制连接起来，让设备能感知并行动。机器人不一定像人，也可能是仓储小车、机械臂或自动检测装置。',research:['把机械、传感器、电路、程序与控制连接起来，让设备能感知并行动。机器人不一定像人，也可能是仓储小车、机械臂或自动检测装置。','机电一体化侧重整机集成；控制研究误差如何被纠正；机器人学研究运动与操作；自主系统还需要定位、感知与规划。'],courses:[{en:'Kinematics',name:'运动学',desc:'由关节角求末端位置'},{en:'Dynamics',name:'动力学',desc:'计算驱动需求'},{en:'Control Theory',name:'控制理论',desc:'用反馈减小误差'},{en:'Sensors and Actuators',name:'传感与执行',desc:'选择测量和驱动器'},{en:'Computer Vision',name:'计算机视觉',desc:'从图像提取信息'},{en:'Motion Planning',name:'运动规划',desc:'寻找可行路线'}],jobs:'控制工程师：调参和分析稳定性；机器人软件工程师：处理定位与规划；集成工程师：联调机械、电气和软件；自动化工程师：改进产线动作与节拍。',tradeoff:'仓储搬运机器人：定位系统估计位置，规划器选择路径，电机控制器跟踪速度。光照、地面反射和轮胎打滑都可能影响效果，因此算法要与传感器和机械一起测试。',distinguish:'机器人通常是多专业合作结果；不少大学把它作为机械、电气或计算机的方向或研究生专业。不要只按专业名称判断。',project:{title:'设计能稳定跟踪路线的小车或仿真',time:'2至4小时完成初版，再用一次课外活动做改进。',start:'使用现有机器人套件，或在仿真中建两轮小车。先让它按预定时间转弯，再加入位置或线路反馈；固定路线长度、弯道与起点。',evidence:'比较完成率、偏离路线次数和用时；改变光照或初始位置测试鲁棒性。',deepen:'调节比例控制参数，记录过小响应慢、过大易振荡的现象；保留失败日志。',fit:'你是否喜欢在机械、程序与传感器之间排查问题？物理、数学和编程都值得学，协作比单项炫技更重要。',links:[{name:'Modern Robotics',url:'https://modernrobotics.northwestern.edu/',step:'先看自由度与运动学视频，数学部分作进阶。'},{name:'Arduino Education',url:'https://www.arduino.cc/education',step:'可用于入门硬件。'}],books:[{title:'Robot Building for Beginners',author:'David Cook',note:'入门读物。'},{title:'Modern Robotics',author:'Kevin M. Lynch and Frank C. Park',note:'配套视频与练习，需线性代数基础。'}],questions:['我能否用一张图解释系统怎样工作，以及限制条件是什么？','哪一项数据推翻了我的最初猜测？如果没有，测试是否足够充分？','如果再给我一天，我会优先改哪个变量，为什么？'],outcome:'一页问题与需求说明、一张设计或流程图、一份原始数据表，以及一段有证据支持的改进解释。'}},
 {name:'工业与系统工程',icon:'▦',en:'INDUSTRIAL',desc:'研究人、设备、信息与流程如何协同。',intro:'工业与系统工程研究人员、设备、信息和流程如何协同，目标可能是减少等待、提高可靠性或合理分配资源，关键是说清优化谁的体验和哪些约束不能违反。',research:['研究人员、设备、信息和流程如何协同。目标可能是减少等待、提高可靠性或合理分配资源；必须先说清楚优化谁的体验和哪些约束不能违反。','运筹学研究决策优化；生产系统研究流程；供应链连接采购与配送；人因工程研究人和系统的交互。部分大学把系统工程单独设置。'],courses:[{en:'Operations Research',name:'运筹学',desc:'把决策写成变量约束与目标'},{en:'Probability and Statistics',name:'概率统计',desc:'处理不确定性'},{en:'Simulation',name:'系统仿真',desc:'模拟排队与故障'},{en:'Supply Chain',name:'供应链',desc:'协调库存和运输'},{en:'Human Factors',name:'人因工程',desc:'降低操作失误'},{en:'Quality Engineering',name:'质量工程',desc:'分析过程波动'}],jobs:'流程工程师：观察瓶颈并试验改进；供应链分析师：权衡库存与缺货；运筹分析师：建立排班配送模型；质量工程师：用数据查找不稳定环节。',tradeoff:'医院排队：增加某一环节的人手不一定缩短总等待，瓶颈可能转移到检查或床位。模型需考虑患者到达波动、紧急程度、公平和人员负荷。',distinguish:'商业管理也研究组织决策，但工业工程通常更强调定量建模、统计和流程设计。系统工程另有需求、接口与全生命周期管理的含义。',project:{title:'优化校园活动的签到流程',time:'2至4小时完成初版，再用一次课外活动做改进。',start:'在不记录个人身份的情况下，测量模拟签到的到达间隔与服务时间。用同学扮演参与者，比较单队多窗口与分队窗口；每种做3轮。',evidence:'记录平均和最长等待时间、每分钟处理人数及工作人员数；不要只看平均值。',deepen:'用电子表格模拟随机到达，检验忙时表现；加入优先通道，讨论效率与公平。',fit:'你是否喜欢找出整个流程为什么卡住？数学、统计和经济学能帮助建立直觉，也要愿意观察人的实际行为。',links:[{name:'INFORMS Explore',url:'https://www.informs.org/Explore',step:'寻找运筹与分析的应用案例，尝试写出目标、决策与约束。'}],books:[{title:'The Goal',author:'Eliyahu M. Goldratt and Jeff Cox',note:'从故事理解瓶颈。'},{title:'Thinking in Systems',author:'Donella H. Meadows',note:'画反馈回路，注意它不是运筹学教材。'}],questions:['我能否用一张图解释系统怎样工作，以及限制条件是什么？','哪一项数据推翻了我的最初猜测？如果没有，测试是否足够充分？','如果再给我一天，我会优先改哪个变量，为什么？'],outcome:'一页问题与需求说明、一张设计或流程图、一份原始数据表，以及一段有证据支持的改进解释。'}},
 {name:'能源工程',icon:'⚡',en:'ENERGY',desc:'研究能源从来源到使用的整条链。',intro:'能源工程研究能源从来源到使用的整条链，包括转换、储存、输送和需求。判断方案需要同时看功率、能量、效率、成本、排放和时间变化。',research:['研究能源从来源到使用的整条链，包括转换、储存、输送和需求。判断方案需要同时看功率、能量、效率、成本、排放和时间变化。','热能研究热机与换热；可再生能源研究风光等来源；储能研究电池等载体；能源系统研究电网与需求匹配。'],courses:[{en:'Energy Conversion',name:'能量转换',desc:'计算输入输出与损失'},{en:'Renewable Energy',name:'可再生能源',desc:'分析资源与波动'},{en:'Thermal Engineering',name:'热工学',desc:'设计热量利用'},{en:'Energy Storage',name:'储能',desc:'区分容量功率与寿命'},{en:'Power Electronics',name:'电力电子',desc:'连接电源储能与负载'},{en:'Energy Systems Analysis',name:'能源系统分析',desc:'比较系统方案'}],jobs:'能源系统工程师：分析供需与设备配置；储能工程师：测试电池系统；热能工程师：改进供热或余热回收；能源分析师：建模情景与成本。细分岗位也常由电气或机械毕业生进入。',tradeoff:'太阳能微电网：中午可能发电多，晚间可能用电多；电池把能量在时间上转移，却存在损耗和容量限制。只知道一天总发电量，不能保证每个小时都有电。',distinguish:'电气重点可能是供电与电能转换；机械重点可能是热与流体；材料重点可能是电极。能源工程综合这些接口，课程重点因学校而异。',project:{title:'为教室建立一天的供能模型',time:'2至4小时完成初版，再用一次课外活动做改进。',start:'列出灯、电脑等设备的额定功率与使用时段，用电子表格做24小时负荷表；设置一条示例光伏发电曲线，明确它是假设而非实测。',evidence:'计算每日用电量kWh、峰值功率kW、缺电小时数，以及给定储能容量下的缺口；将充放电效率列为假设。',deepen:'增加电池容量并改变使用时段，比较哪个方案减少更多缺口；可用小太阳能套件测倾角，不拆装锂电池。',fit:'你是否喜欢用数字检查环保主张？物理、数学、化学和经济学都能进入这个领域。',links:[{name:'IEA Energy System',url:'https://www.iea.org/energy-system',step:'先比较Solar PV、Electric Vehicles与Buildings；注意资料的年份和地区。'}],books:[{title:'Sustainable Energy Without the Hot Air',author:'David J. C. MacKay',note:'练习数量级估算，旧数据需更新。'},{title:'Energy and Civilization A History',author:'Vaclav Smil',note:'理解能源与社会的长期联系。'}],questions:['我能否用一张图解释系统怎样工作，以及限制条件是什么？','哪一项数据推翻了我的最初猜测？如果没有，测试是否足够充分？','如果再给我一天，我会优先改哪个变量，为什么？'],outcome:'一页问题与需求说明、一张设计或流程图、一份原始数据表，以及一段有证据支持的改进解释。'}}
];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>new Date(v*1000).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});
async function api(path,data){const r=await fetch('/api/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const result=await r.json();if(!r.ok)throw new Error(result.error||'暂时无法连接，请稍后再试。');return result;}
function toast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),4000);}
function showModal(html){modalBody.innerHTML=html;if(!modal.open)modal.showModal();}
function formError(form,text){const error=form.querySelector('.error');error.textContent=text;error.classList.add('visible');}
function errorBox(){return '<div class="error" role="alert"></div>';}
async function formSubmit(form,fn){const button=form.querySelector('button[type=submit]');button.disabled=true;form.querySelector('.error')?.classList.remove('visible');try{await fn(new FormData(form));}catch(e){formError(form,e.message);}finally{button.disabled=false;}}
const roleName=u=>u?.is_admin?'管理员':u?.role==='engineer'?'工程师':'学生';
function accountLabel(){
 document.querySelector('#account').textContent=me?`${me.name} · ${roleName(me)}`:'登录 / 注册 ↗';
 const nav=document.querySelector('nav');
 nav.innerHTML=me?.is_admin?'<a href="#admin">管理总览</a><a href="#admin/users">全部用户</a><a href="#admin/requests">全部咨询</a><a href="#guide">如何使用</a><a href="#student">学生端预览</a><a href="#mentor">工程师端预览</a>':me?.role==='engineer'?'<a href="#mentor">工程师工作台</a><a href="#workspace">指导项目</a><a href="#profile">个人资料</a><a href="#guide">如何使用</a><a href="#student">浏览学生端</a><a href="#about">关于我们</a>':me?'<a href="#home">学生首页</a><a href="#engineers">寻找工程师</a><a href="#explore">探索工程</a><a href="#workspace">我的咨询</a><a href="#guide">如何使用</a><a href="#about">关于我们</a>':'<a href="#home">首页</a><a href="#guide">如何使用</a><a href="#engineers">寻找工程师</a><a href="#explore">探索工程</a><a href="#about">关于我们</a>';
}
